package server.bots;
import client.Character;import server.maps.MapleMap;import server.life.Monster;import java.awt.Point;import org.junit.jupiter.api.Test;import static org.mockito.Mockito.*;
class BotPinkBeanDescentTest {
 @Test void leavingUpperInnerPlatformStagesOutsideTheLiveBirdBeforeDescending(){var b=mock(Character.class);var map=mock(MapleMap.class);var e=new BotEntry(b,b,null);when(b.getMap()).thenReturn(map);when(b.getEventInstance()).thenReturn(mock(scripting.event.EventInstanceManager.class));when(b.getPosition()).thenReturn(new Point(-350,-456));when(map.getMonsterById(8820005)).thenReturn(mock(Monster.class));try(var pink=mockStatic(BotPinkBeanRun.class);var horn=mockStatic(BotHorntailMovement.class);var walking=mockStatic(BotZakumPqRun.class)){pink.when(()->BotPinkBeanRun.inInstance(b)).thenReturn(true);horn.when(()->BotHorntailMovement.approach(b,new Point(-550,-99))).thenReturn(new Point(-550,-99));BotPinkBeanMovement.walkTo(e,b,new Point(-550,-99),true);walking.verify(()->BotZakumPqRun.walkTo(e,b,new Point(-550,-456),true));}}
 @Test void approachingTheTopFirstWalksUnderTheSageToTheSafeRopeBase(){var b=mock(Character.class);var map=mock(MapleMap.class);var e=new BotEntry(b,b,null);when(b.getMap()).thenReturn(map);when(b.getPosition()).thenReturn(new Point(-695,-42));when(map.getMonsterById(8820003)).thenReturn(mock(Monster.class));try(var pink=mockStatic(BotPinkBeanRun.class);var horn=mockStatic(BotHorntailMovement.class);var walking=mockStatic(BotZakumPqRun.class)){pink.when(()->BotPinkBeanRun.inInstance(b)).thenReturn(true);horn.when(()->BotHorntailMovement.approach(b,new Point(-350,-456))).thenReturn(new Point(-350,-456));BotPinkBeanMovement.walkTo(e,b,new Point(-350,-456),true);walking.verify(()->BotZakumPqRun.walkTo(e,b,new Point(-508,-42),true));}}
}
